/**
 * DataPlaneService is the data plane of Sylphx Data: object bytes, key-value
 * entries (strings, counters, hashes, lists, and sorted sets), and search
 * documents in an environment's buckets, KV namespaces, and search indexes. It is
 * served by Data itself at its origin, not by the Resource API, and is called
 * with the environment's secret key (`SYLPHX_API_KEY`); the key's org,
 * project, and environment are the tenant. Every call carries a new
 * `Sylphx-Effect-Id`, which the SDK sends and reuses on retries.
 *
 * The buckets, namespaces, and indexes themselves are Resources of
 * DataService. The
 * messages here are Data's wire format
 * (`services/data/proto/sylphx/data/v1/data.proto`), field for field; Data
 * answers ProtoJSON (camelCase names, 64-bit integers and bytes as strings).
 *
 * Namespace of Sylphx Data on `Sylphx`.
 */
export class DataApi {
	/** The `objects` collection. */
	readonly objects: ObjectsCollection
	/** The `kv` collection. */
	readonly kv: KvCollection
	/** The `documents` collection. */
	readonly documents: DocumentsCollection
	/** The `search` collection. */
	readonly search: SearchCollection
	/** The `databases` collection. */
	readonly databases: DatabasesCollection
	/** The `kv_namespaces` collection. */
	readonly kvNamespaces: KvNamespacesCollection
	/** The `buckets` collection. */
	readonly buckets: BucketsCollection
	/** The `search_indexes` collection. */
	readonly searchIndexes: SearchIndexesCollection

	constructor(client: runtime.Client) {
		this.objects = new ObjectsCollection(client)
		this.kv = new KvCollection(client)
		this.documents = new DocumentsCollection(client)
		this.search = new SearchCollection(client)
		this.databases = new DatabasesCollection(client)
		this.kvNamespaces = new KvNamespacesCollection(client)
		this.buckets = new BucketsCollection(client)
		this.searchIndexes = new SearchIndexesCollection(client)
	}
}

